async function getUserPreferences() {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      // User-specific data changes on each request, so do not prerender or cache it.
      cache: 'no-store',
    })
    return await res.json()
  } catch {
    // Return mock data when the request fails, including during build.
    return { theme: 'light', notifications: true }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()
  const entries =
    preferences && typeof preferences === 'object'
      ? Object.entries(preferences)
      : []

  return (
    <div>
      <h2>User Dashboard</h2>
      {entries.length > 0 ? (
        <ul>
          {entries.map(([key, value]) => (
            <li key={key}>
              {key}:{' '}
              {typeof value === 'object' && value !== null
                ? JSON.stringify(value)
                : String(value)}
            </li>
          ))}
        </ul>
      ) : (
        <p>No user preferences available</p>
      )}
    </div>
  )
}

